SourceCode.Declaration:
/// <summary>
/// The <c>UPSJournalCheckPost</c> is factory class to create class for check/post UPS journals.
/// </summary>
public abstract class UPSJournalCheckPost extends JournalCheckPost
{
}

Method.Source:
protected void initCheckPost(
    JournalCheckPostType _journalCheckPostType,
    JournalTableData _journalTableData,
    JournalTransData _journalTransData = null)
{
    this.journalTableData = _journalTableData;

    JournalTableMap journalTable = journalTableData.journalTable();
    this.initializeJournalCheckPost(false, true, _journalCheckPostType, journalTable.TableId, journalTable.JournalId, _journalTransData);
}

public final void initializeJournalCheckPost(
    boolean                 _autoBlock,
    boolean                 _showInfoResult,
    JournalCheckPostType    _journalCheckPostType,
    TableId                 _tableId,
    JournalId               _journalId,
    JournalTransData        _journalTransData = null)
{
    super(_autoBlock, _showInfoResult, _journalCheckPostType, _tableId, _journalId, _journalTransData);

    this.parmJournalTableId(_tableId);  // in order to find the specific lastValue (see lastValueDesignName)
    this.parmJournalId(_journalId);
    this.getLast();

    this.parmAutoBlock(_autoBlock);
    this.parmShowInfoResult(_showInfoResult);
    this.parmJournalCheckPostType(_journalCheckPostType);
    this.parmThrowCheckFailed(false);
}

public static void main(Args args)
{
    JournalForm journalForm = JournalForm::fromArgs(args);
    UPSJournalCheckPost journalCheckPost = UPSJournalCheckPost::fromArgs(args);

    journalForm.runbaseMainStart();

    if (!journalCheckPost.prompt())
    {
        if (! journalCheckPost.batchInfo().parmBatchExecute())
        {
            journalForm.runbaseMainCancel(journalCheckPost.journalId);
        }
        return;
    }

    try
    {
        journalCheckPost.runOperation();
        journalForm.runbaseMainEnd(journalCheckPost,false);
    }
    catch (Exception::Error)
    {
        journalForm.runbaseMainEnd(journalCheckPost,true);
    }
    catch (Exception::UpdateConflictNotRecovered)
    {
        journalForm.runbaseMainEnd(journalCheckPost,true);
        throw Exception::UpdateConflictNotRecovered;
    }
}

public final static UPSJournalCheckPost fromArgs(Args args)
{
    JournalForm journalForm = JournalForm::fromArgs(args);
    JournalTransData journalTransData = journalForm.journalTransData();
    JournalTableData journalTableData = journalForm.journalTableData();
    UPSJournalCheckPost journalCheckPost;

    // TODO: factory method to construct UPSJournalCheckPost vary from journal table type.
    switch (args.callerName())
    {
        case formStr(UPSPriceTermJournalTable):
        case formStr(UPSPriceTermJournalTrans):
            journalCheckPost = new UPSJournalCheckPost_PriceTerm();
            break;
    }

    journalCheckPost.initCheckPost(args.parmEnum(), journalTableData, journalTransData);

    return journalCheckPost;
}

public ClassDescription caption()
{
    ClassDescription ret;

    if (journalCheckPostType == JournalCheckPostType::Check)
    {
        ret = strFmt("@UnifiedPricingService:UPSJournalCheckPost_Caption_Check", this.journalId);
    }
    else
    {
        ret = strFmt("@UnifiedPricingService:UPSJournalCheckPost_Caption_Post", this.journalId);
    }

    return ret;
}
